<?php
declare(strict_types=1);session_start();require_once __DIR__.'/manager_payout_common.php';
header('Cache-Control: no-store');header('X-Frame-Options: DENY');
if(!empty($_SESSION['_imp'])||!empty($_SESSION['_manager_edit'])||!(($_SESSION['is_admin']??false)||($_SESSION['ID_OK']??null)==1)){http_response_code(403);exit('사이트 관리자 계정으로 로그인해 주세요.');}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf'],$_POST['csrf']))throw new RuntimeException('새로고침 후 다시 시도해 주세요.');
 if(($_POST['decision']??'')==='paid'&&($_POST['sent']??'')!=='1')throw new RuntimeException('실제 송금 완료 여부를 확인해 주세요.');
 mp_process((string)($_SESSION['member_id']??'site-admin'),(string)($_POST['id']??''),(string)($_POST['decision']??''),trim((string)($_POST['note']??'')));$_SESSION['payout_admin_notice']='처리했습니다.';
 }catch(Throwable $e){$_SESSION['payout_admin_notice']=$e->getMessage();}
 header('Location: /admin_manager_payouts.php',true,303);exit;
}
$members=mg_members();$state=mg_read(mg_state_file());$rows=array_values($state['payouts']??[]);usort($rows,fn($a,$b)=>(($a['status']!=='pending')<=>($b['status']!=='pending'))?:strcmp($b['at'],$a['at']));
$totals=['pending'=>0,'paid'=>0,'rejected'=>0];$pendingAmount=0;
foreach($rows as $r){$totals[$r['status']]++;if($r['status']==='pending')$pendingAmount+=(int)$r['amount'];}

$managerRows=[];$summary=['held'=>0,'available'=>0,'pending'=>0,'paid'=>0,'deficit'=>0];
$linked=[];foreach($members as $id=>$m){if(!is_array($m)||!mg_active($m,'building'))continue;$owner=mg_connection_manager($m,$members);if($owner!==''&&mg_link_status((string)$id,$m,$state)==='accepted')$linked[$owner]=($linked[$owner]??0)+1;}
foreach($members as $uid=>$m){
 if(!is_array($m)||($m['role']??'')!=='agency')continue;
 $b=mp_balance($state,(string)$uid,$m);$b['held']=max(0,$b['earned']-$b['paid']);
 foreach($summary as $key=>$_)$summary[$key]+=$b[$key];
 $account=$state['payout_accounts'][mp_account_key((string)$uid,$m)]??null;
 $managerRows[]=['uid'=>(string)$uid,'name'=>(string)($m['nickname']??$uid),'code'=>(string)($m['manager_code']??''),'created'=>(string)($m['created']??''),'status'=>(string)($m['status']??'active'),'clients'=>$linked[$uid]??0,'balance'=>$b,'account'=>$account];
}
usort($managerRows,fn($a,$b)=>strcmp($b['created'],$a['created']));
