<div class="filters"><input id="manager-search" type="search" aria-label="가입 매니저 검색" placeholder="매니저 이름 · 아이디 · 코드 검색"><select id="manager-filter" aria-label="매니저 현황 필터"><option value="all">전체 매니저</option><option value="pending">출금 신청 중</option><option value="balance">출금 가능 코인 보유</option><option value="missing">계좌 미등록</option><option value="deficit">정산 확인 필요</option></select><select id="manager-sort" aria-label="매니저 정렬"><option value="new">최근 가입순</option><option value="balance">보유 코인순</option><option value="clients">담당 유저순</option></select></div><p id="manager-count" role="status"></p>
<div class="table-wrap"><table><thead><tr><th>매니저 / 코드</th><th>가입일 / 상태</th><th>담당 유저</th><th>보유 코인</th><th>출금 가능</th><th>신청 중</th><th>지급 완료</th><th>계좌 / 내역</th></tr></thead><tbody id="manager-table">
<?php foreach($managerRows as $i=>$m):$b=$m['balance'];?><tr data-manager-row data-order="<?=$i?>" data-search="<?=mg_e($m['uid'].' '.$m['name'].' '.$m['code'])?>" data-held="<?=$b['held']?>" data-clients="<?=$m['clients']?>" data-pending="<?=$b['pending']?>" data-available="<?=$b['available']?>" data-deficit="<?=$b['deficit']?>" data-account="<?=$m['account']?'1':'0'?>"><td><strong><?=mg_e($m['name'])?></strong><small><?=mg_e($m['uid'])?><br><?=mg_e($m['code']?:'코드 미발급')?></small></td><td><?=mg_e(substr($m['created'],0,10)?:'미등록')?><small><?=mg_e(['active'=>'활성','pending'=>'승인 대기','blocked'=>'차단','suspended'=>'정지','deleted'=>'탈퇴'][$m['status']]??$m['status'])?></small></td><td><?=$m['clients']?>명</td><td><b><?=number_format($b['held'])?></b>개</td><td><?=number_format($b['available'])?>개<?php if($b['deficit']):?><small class="warn">정산 부족 <?=$b['deficit']?>개</small><?php endif;?></td><td><?=number_format($b['pending'])?>개</td><td><?=number_format($b['paid'])?>개</td><td><small><?=$m['account']?'등록됨':'미등록'?></small><button type="button" data-manager-payouts="<?=mg_e($m['uid'])?>">출금 내역</button></td></tr><?php endforeach;?></tbody></table></div><p id="manager-empty" hidden>해당 조건의 매니저가 없습니다.</p>
