<div class="stats"><div class="stat"><span>처리 대기</span><b><?=$totals['pending']?>건</b></div><div class="stat"><span>대기 신청 금액</span><b><?=number_format($pendingAmount)?>원</b></div><div class="stat"><span>지급 완료</span><b><?=$totals['paid']?>건</b></div></div>
<div class="filters"><input type="search" id="payout-search" aria-label="매니저 검색" placeholder="매니저 이름 · 아이디 · 신청번호 검색"><select id="payout-filter" aria-label="처리 상태"><option value="pending">처리 대기</option><option value="all">전체 신청</option><option value="paid">지급 완료</option><option value="rejected">반려</option></select></div><p id="payout-result" role="status"></p>
<?php if(!$rows): ?><p>출금 신청이 없습니다.</p><?php endif;?>
<?php foreach($rows as $r):$pending=$r['status']==='pending';$me=$members[$r['manager']]??[];$blocked=!mg_active($me,'agency')||!mp_owned($r,$r['manager'],$me)||mp_balance($state,$r['manager'],$me)['deficit']>0;?>
<article data-manager="<?=mg_e($r['manager'])?>" data-payout-row data-status="<?=mg_e($r['status'])?>" data-search="<?=mg_e($r['name'].' '.$r['manager'].' '.$r['id'].' '.($me['nickname']??''))?>"><div class="payout-head"><div><strong><?=mg_e($r['name'])?> 매니저</strong><div class="code">아이디 <?=mg_e($r['manager'])?><?php if(mp_owned($r,$r['manager'],$me)&&!empty($me['manager_code'])): ?> · 코드 <?=mg_e($me['manager_code'])?><?php endif;?></div></div><span class="badge"><?=mg_e(['pending'=>'처리 대기','paid'=>'지급 완료','rejected'=>'반려'][$r['status']])?></span></div><p><?=number_format($r['coins'])?>코인 / <b><?=number_format($r['amount'])?>원</b> · <?=mg_e(['pending'=>'신청 대기','paid'=>'지급 완료','rejected'=>'반려'][$r['status']])?></p><small>신청 <?=mg_e($r['at'])?> · 신청번호 <?=mg_e(substr($r['id'],0,12))?></small>
<p class="account-box">송금 계좌<br><?=mg_e($r['account']['bank'])?> / <?=mg_e($pending?$r['account']['number']:mp_mask($r['account']['number']))?> / 예금주 <?=mg_e($r['account']['holder'])?></p>
<?php if($pending): ?><?php if($blocked):?><p class="warn">회원 상태 또는 환불로 인한 코인 부족을 확인하세요. 지급 완료 처리가 차단됩니다.</p><?php endif;?>
<form method="post"><input type="hidden" name="csrf" value="<?=mg_e($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=mg_e($r['id'])?>"><label>처리 메모 / 반려 사유 <input name="note" maxlength="200" placeholder="이체 확인번호 또는 반려 사유"></label><label><input type="checkbox" name="sent" value="1"> 위 계좌와 금액으로 실제 송금을 완료했습니다.</label><button name="decision" value="paid" <?=$blocked?'disabled':''?>>지급 완료 처리</button> <button name="decision" value="rejected">반려 · 코인 반환</button></form>
<?php else: ?><p><?=mg_e($r['processed_at']??'')?></p><p class="note"><?=mg_e($r['note'])?></p><?php endif;?></article><?php endforeach;?><p id="payout-empty" hidden>해당 조건의 출금 신청이 없습니다.</p></main><script>
(()=>{let exactManager=null;const input=document.getElementById('payout-search'),filter=document.getElementById('payout-filter'),rows=[...document.querySelectorAll('[data-payout-row]')];function apply(){let n=0;const q=input.value.trim().toLocaleLowerCase();for(const row of rows){row.hidden=!(filter.value==='all'||row.dataset.status===filter.value)||!row.dataset.search.toLocaleLowerCase().includes(q)||(exactManager!==null&&row.dataset.manager!==exactManager);if(!row.hidden)n++;}document.getElementById('payout-result').textContent=n+'건의 신청';document.getElementById('payout-empty').hidden=n>0;}input.addEventListener('input',()=>{exactManager=null;apply();});filter.addEventListener('change',apply);document.querySelectorAll('[data-manager-payouts]').forEach(b=>b.addEventListener('click',()=>{exactManager=b.dataset.managerPayouts;input.value=exactManager;filter.value='all';apply();document.getElementById('payout-section').scrollIntoView({behavior:'smooth'});}));apply();})();
</script><script>
(()=>{const input=document.getElementById('manager-search'),filter=document.getElementById('manager-filter'),sort=document.getElementById('manager-sort'),body=document.getElementById('manager-table'),rows=[...body.querySelectorAll('[data-manager-row]')];function apply(){const q=input.value.trim().toLocaleLowerCase();let n=0;rows.sort((a,b)=>sort.value==='new'?Number(a.dataset.order)-Number(b.dataset.order):Number(b.dataset[sort.value==='balance'?'held':'clients'])-Number(a.dataset[sort.value==='balance'?'held':'clients']));for(const row of rows){const d=row.dataset;const match=filter.value==='all'||(filter.value==='pending'&&Number(d.pending)>0)||(filter.value==='balance'&&Number(d.available)>0)||(filter.value==='missing'&&d.account==='0')||(filter.value==='deficit'&&Number(d.deficit)>0);row.hidden=!match||!d.search.toLocaleLowerCase().includes(q);body.append(row);if(!row.hidden)n++;}document.getElementById('manager-count').textContent=n+'명 / 전체 '+rows.length+'명';document.getElementById('manager-empty').hidden=n>0;}input.addEventListener('input',apply);filter.addEventListener('change',apply);sort.addEventListener('change',apply);apply();})();
</script></html>
